import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  User, 
  Building2, 
  Mail, 
  Lock, 
  Phone, 
  Hash, 
  GraduationCap, 
  BookOpen, 
  TrendingUp, 
  Globe, 
  MapPin, 
  ShieldCheck, 
  ArrowRight, 
  ChevronRight,
  Sparkles,
  CheckCircle2,
  XCircle,
  Eye,
  EyeOff
} from 'lucide-react';
import { useStudents } from '../../hooks/useStudents';
import { useEmployers } from '../../hooks/useEmployers';

const Register = () => {
  const navigate = useNavigate();
  const { registerStudent, loading: studentLoading } = useStudents();
  const { registerEmployer, loading: employerLoading } = useEmployers();

  const [activeTab, setActiveTab] = useState('student');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const [studentForm, setStudentForm] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    phone: '',
    rollNumber: '',
    department: '',
    year: '',
    cgpa: ''
  });

  const [employerForm, setEmployerForm] = useState({
    companyName: '',
    email: '',
    password: '',
    confirmPassword: '',
    phone: '',
    website: '',
    industry: '',
    address: '',
    contactPerson: '',
    description: ''
  });

  const handleStudentChange = (e) => {
    setStudentForm({ ...studentForm, [e.target.name]: e.target.value });
  };

  const handleEmployerChange = (e) => {
    setEmployerForm({ ...employerForm, [e.target.name]: e.target.value });
  };

  const validateStudentForm = () => {
    if (!studentForm.name || !studentForm.email || !studentForm.password) {
      setError('Essential fields must be fulfilled.');
      return false;
    }
    if (studentForm.password !== studentForm.confirmPassword) {
      setError('Secret protocols do not match.');
      return false;
    }
    if (studentForm.password.length < 6) {
      setError('Security protocol requires at least 6 characters.');
      return false;
    }
    return true;
  };

  const validateEmployerForm = () => {
    if (!employerForm.companyName || !employerForm.email || !employerForm.password) {
      setError('Corporate identifiers must be provided.');
      return false;
    }
    if (employerForm.password !== employerForm.confirmPassword) {
      setError('Secret protocols do not match.');
      return false;
    }
    if (employerForm.password.length < 6) {
      setError('Security protocol requires at least 6 characters.');
      return false;
    }
    return true;
  };

  const handleStudentSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!validateStudentForm()) return;

    try {
      setLoading(true);
      const studentData = {
        ...studentForm,
        userType: 'student',
        isEligible: true,
        skills: [],
        certifications: []
      };

      await registerStudent(studentData);
      setSuccess('Talent cataloged. Welcome to the elite.');
      setTimeout(() => navigate('/login'), 2000);
    } catch (error) {
      setError(error.message || 'Transmission failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleEmployerSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!validateEmployerForm()) return;

    try {
      setLoading(true);
      const employerData = {
        ...employerForm,
        userType: 'employer',
        isVerified: false
      };

      await registerEmployer(employerData);
      setSuccess('Institution registered. Verification protocol initiated.');
      setTimeout(() => navigate('/login'), 2000);
    } catch (error) {
      setError(error.message || 'Transmission failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background text-charcoal-800 font-nexed flex items-center justify-center p-6 relative overflow-hidden selection:bg-charcoal-900 selection:text-white">

      {/* Background Decorative Blobs */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-[-10%] right-[-10%] w-[600px] h-[600px] bg-charcoal-100 rounded-full blur-[150px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[600px] h-[600px] bg-charcoal-100 rounded-full blur-[150px] animate-pulse" style={{ animationDelay: '2s' }}></div>
      </div>

      <div className="w-full max-w-5xl grid grid-cols-1 lg:grid-cols-12 gap-0 bg-white rounded-[3.5rem] border border-charcoal-100 overflow-hidden shadow-2xl z-10 animate-fade-in-up">

        {/* Sidebar Info */}
        <div className="lg:col-span-4 bg-charcoal-900 p-12 border-r border-charcoal-100 flex flex-col justify-between relative overflow-hidden">
           <div className="absolute inset-0 bg-charcoal-gradient opacity-[0.05]"></div>
           <div className="relative z-10">
              <Link to="/" className="flex items-center gap-3 mb-16 group">
                <div className="w-10 h-10 bg-charcoal-gradient rounded-xl flex items-center justify-center text-white shadow-charcoal group-hover:rotate-12 transition-transform duration-500">
                   <Sparkles size={20} />
                </div>
                <span className="text-2xl font-nexed font-black text-white tracking-tighter">Jobsy</span>
              </Link>

              <h2 className="text-4xl font-nexed font-bold text-white mb-6 leading-tight">Join the <br /><span className="text-white/80 italic">Elite Circle.</span></h2>
              <p className="text-pearl-500 font-light leading-relaxed mb-12 italic">"Crafting legacies, one connection at a time. The world's most exclusive professional registry awaits."</p>

              <div className="space-y-8">
                 <div className="flex gap-4 items-center group">
                    <div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-white/60 group-hover:border-white/40 transition-all">
                       <ShieldCheck size={20} />
                    </div>
                    <span className="text-[10px] font-nexed font-black uppercase tracking-[0.2em] text-pearl-600 group-hover:text-pearl-300 transition-colors">Verified Integrity</span>
                 </div>
                 <div className="flex gap-4 items-center group">
                    <div className="w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-white/60 group-hover:border-white/40 transition-all">
                       <Globe size={20} />
                    </div>
                    <span className="text-[10px] font-nexed font-black uppercase tracking-[0.2em] text-pearl-600 group-hover:text-pearl-300 transition-colors">Global Exposure</span>
                 </div>
              </div>
           </div>

           <div className="relative z-10 pt-12">
              <p className="text-[10px] font-nexed font-black text-pearl-800 uppercase tracking-[0.3em] mb-4">Already Cataloged?</p>
              <Link to="/login" className="inline-flex items-center gap-2 text-white font-nexed font-bold hover:text-white/80 transition-colors group">
                 Sign In to Registry <ChevronRight size={16} className="group-hover:translate-x-1 transition-transform" />
              </Link>
           </div>
        </div>

        {/* Form Area */}
        <div className="lg:col-span-8 p-10 md:p-16 bg-white">

           {/* Custom Tab Switcher */}
           <div className="flex gap-2 p-1.5 bg-charcoal-50 rounded-2xl border border-charcoal-100 mb-12 max-w-sm">
              <button 
                onClick={() => { setActiveTab('student'); setError(''); }}
                className={`flex-1 py-3 rounded-xl text-[10px] font-nexed font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'student' ? 'bg-black text-white shadow-xl' : 'text-charcoal-400 hover:text-charcoal-800'}`}
              >
                <User size={14} /> Talent
              </button>
              <button 
                onClick={() => { setActiveTab('employer'); setError(''); }}
                className={`flex-1 py-3 rounded-xl text-[10px] font-nexed font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'employer' ? 'bg-black text-white shadow-xl' : 'text-charcoal-400 hover:text-charcoal-800'}`}
              >
                <Building2 size={14} /> Institution
              </button>
           </div>

           {error && (
              <div className="p-4 rounded-xl bg-rose-600/10 border border-rose-600/20 text-rose-600 text-[10px] font-nexed font-black uppercase tracking-widest mb-8 flex items-center gap-3 animate-shake">
                 <XCircle size={18} /> {error}
              </div>
            )}

            {success && (
              <div className="p-4 rounded-xl bg-emerald-600/10 border border-emerald-600/20 text-emerald-600 text-[10px] font-nexed font-black uppercase tracking-widest mb-8 flex items-center gap-3 animate-fade-in">
                 <CheckCircle2 size={18} /> {success}
              </div>
            )}

           {activeTab === 'student' ? (
             <form onSubmit={handleStudentSubmit} className="space-y-8 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Full Name</label>
                      <div className="relative group">
                         <User className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="text" name="name" value={studentForm.name} onChange={handleStudentChange} placeholder="Ex: Julian Thorne" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Secure Email</label>
                      <div className="relative group">
                         <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="email" name="email" value={studentForm.email} onChange={handleStudentChange} placeholder="julian@excellence.edu" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Protocol Secret (Password)</label>
                      <div className="relative group">
                         <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type={showPassword ? "text" : "password"} name="password" value={studentForm.password} onChange={handleStudentChange} placeholder="••••••••" required className="w-full px-5 py-4 pl-14 pr-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                         <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-charcoal-300 hover:text-charcoal-900 transition-colors">
                            {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                         </button>
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Confirm Secret</label>
                      <div className="relative group">
                         <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="password" name="confirmPassword" value={studentForm.confirmPassword} onChange={handleStudentChange} placeholder="••••••••" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Secure Line (Phone)</label>
                      <div className="relative group">
                         <Phone className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="tel" name="phone" value={studentForm.phone} onChange={handleStudentChange} placeholder="+1 (555) 000-0000" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Talent ID (Roll No.)</label>
                      <div className="relative group">
                         <Hash className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="text" name="rollNumber" value={studentForm.rollNumber} onChange={handleStudentChange} placeholder="TH-990-2024" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Vertical</label>
                      <select name="department" value={studentForm.department} onChange={handleStudentChange} className="w-full px-5 py-4 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 appearance-none cursor-pointer">
                         <option value="">Select Department</option>
                         <option value="Computer Science">Computer Science</option>
                         <option value="Information Technology">Information Technology</option>
                         <option value="Electronics">Electronics</option>
                         <option value="Mechanical">Mechanical</option>
                         <option value="Civil">Civil</option>
                         <option value="Electrical">Electrical</option>
                      </select>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Academic Tier</label>
                      <select name="year" value={studentForm.year} onChange={handleStudentChange} className="w-full px-5 py-4 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 appearance-none cursor-pointer">
                         <option value="">Select Year</option>
                         <option value="1">1st Year</option>
                         <option value="2">2nd Year</option>
                         <option value="3">3rd Year</option>
                         <option value="4">4th Year</option>
                      </select>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Metric (CGPA)</label>
                      <div className="relative group">
                         <TrendingUp className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="number" step="0.01" min="0" max="10" name="cgpa" value={studentForm.cgpa} onChange={handleStudentChange} placeholder="9.50" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <button 
                  type="submit" 
                  disabled={loading}
                  className="w-full py-5 rounded-[2rem] bg-charcoal-gradient text-white font-nexed font-black uppercase tracking-[0.3em] text-xs shadow-charcoal hover:scale-[1.02] active:scale-95 transition-all duration-300 flex items-center justify-center gap-4 group mt-4"
                >
                   {loading ? (
                     <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Cataloging...</>
                   ) : (
                     <>Catalog Portfolio <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" /></>
                   )}
                </button>
             </form>
           ) : (
             <form onSubmit={handleEmployerSubmit} className="space-y-8 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Corporate Identity</label>
                      <div className="relative group">
                         <Building2 className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="text" name="companyName" value={employerForm.companyName} onChange={handleEmployerChange} placeholder="Ex: Thorne Industries" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Corporate Email</label>
                      <div className="relative group">
                         <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="email" name="email" value={employerForm.email} onChange={handleEmployerChange} placeholder="hq@thorne.co" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Security Key</label>
                      <div className="relative group">
                         <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type={showPassword ? "text" : "password"} name="password" value={employerForm.password} onChange={handleEmployerChange} placeholder="••••••••" required className="w-full px-5 py-4 pl-14 pr-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                         <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-charcoal-300 hover:text-charcoal-900 transition-colors">
                            {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                         </button>
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Confirm Key</label>
                      <div className="relative group">
                         <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="password" name="confirmPassword" value={employerForm.confirmPassword} onChange={handleEmployerChange} placeholder="••••••••" required className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Corporate HQ Phone</label>
                      <div className="relative group">
                         <Phone className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="tel" name="phone" value={employerForm.phone} onChange={handleEmployerChange} placeholder="+1 (555) 000-0000" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Digital Domain (Website)</label>
                      <div className="relative group">
                         <Globe className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="url" name="website" value={employerForm.website} onChange={handleEmployerChange} placeholder="https://thorne.co" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Sector (Industry)</label>
                      <select name="industry" value={employerForm.industry} onChange={handleEmployerChange} className="w-full px-5 py-4 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 appearance-none cursor-pointer">
                         <option value="">Select Industry</option>
                         <option value="Technology">Technology</option>
                         <option value="Finance">Finance</option>
                         <option value="Healthcare">Healthcare</option>
                         <option value="Manufacturing">Manufacturing</option>
                         <option value="Consulting">Consulting</option>
                         <option value="Other">Other</option>
                      </select>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">HQ Base (Address)</label>
                      <div className="relative group">
                         <MapPin className="absolute left-5 top-1/2 -translate-y-1/2 text-charcoal-300 group-focus-within:text-charcoal-900 transition-colors" size={18} />
                         <input type="text" name="address" value={employerForm.address} onChange={handleEmployerChange} placeholder="Silicon Valley, CA" className="w-full px-5 py-4 pl-14 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-medium text-charcoal-900 placeholder-charcoal-200" />
                      </div>
                   </div>
                </div>

                <div className="space-y-2">
                   <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] ml-1">Corporate Mission</label>
                   <textarea name="description" rows={3} value={employerForm.description} onChange={handleEmployerChange} placeholder="Briefly articulate your corporate mission and culture..." className="w-full px-5 py-4 rounded-2xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-light text-charcoal-800 resize-none leading-relaxed" />
                </div>

                <button 
                  type="submit" 
                  disabled={loading}
                  className="w-full py-5 rounded-[2rem] bg-charcoal-gradient text-white font-nexed font-black uppercase tracking-[0.3em] text-xs shadow-charcoal hover:scale-[1.02] active:scale-95 transition-all duration-300 flex items-center justify-center gap-4 group mt-4"
                >
                   {loading ? (
                     <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Initiating Registry...</>
                   ) : (
                     <>Register Institution <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" /></>
                   )}
                </button>
             </form>
           )}
        </div>
      </div>
    </div>
  );
};

export default Register;
